param([Parameter(Mandatory)][ValidatePattern('^golang:1\.27\.0@sha256:[a-f0-9]{64}$')][string]$GoImage,[Parameter(Mandatory)][ValidatePattern('^gcr\.io/distroless/static-debian12:nonroot@sha256:[a-f0-9]{64}$')][string]$RuntimeImage,[Parameter(Mandatory)][uri]$ViewerOrigin,[Parameter(Mandatory)][string[]]$TurnUrls,[Parameter(Mandatory)][string]$TurnSecret,[Parameter(Mandatory)][string]$NodeSecret,[Parameter(Mandatory)][string]$Certificate,[Parameter(Mandatory)][string]$PrivateKey,[Parameter(Mandatory)][string]$Destination)
$ErrorActionPreference='Stop'
if($ViewerOrigin.Scheme-ne'https'-or$ViewerOrigin.UserInfo-or$ViewerOrigin.Query-or$ViewerOrigin.Fragment-or$ViewerOrigin.AbsolutePath-ne'/'){throw 'Exact HTTPS Viewer origin required'}
if(!$TurnUrls.Count-or$TurnUrls.Count-gt8-or@($TurnUrls|Where-Object {$_-notmatch'^turns?:[A-Za-z0-9.-]+:2500[23]\?transport=tcp$'}).Count){throw 'Explicit authenticated TCP/TLS TURN URLs on 25002/25003 required'}
foreach($file in @($TurnSecret,$NodeSecret)){if((Get-Item -LiteralPath $file).Length-gt256-or[IO.File]::ReadAllText((Resolve-Path -LiteralPath $file)).Trim()-notmatch'^[A-Za-z0-9_-]{32,128}$'){throw 'Protected 32..128 character credential required'}}
$target=[IO.Path]::GetFullPath($Destination);if(Test-Path -LiteralPath $target){throw 'New deployment staging directory required'}
New-Item -ItemType Directory -Path (Join-Path $target 'private/tls') -Force|Out-Null;New-Item -ItemType Directory -Path (Join-Path $target 'audit')|Out-Null
if($env:OS-eq'Windows_NT'){$acl=New-Object Security.AccessControl.DirectorySecurity;$acl.SetAccessRuleProtection($true,$false);$acl.SetOwner((New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')));foreach($sid in @('S-1-5-18','S-1-5-32-544')){$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($sid)),'FullControl','ContainerInherit,ObjectInherit','None','Allow')))};Set-Acl -LiteralPath $target -AclObject $acl}
Copy-Item -LiteralPath $TurnSecret -Destination (Join-Path $target 'private/turn.secret');Copy-Item -LiteralPath $NodeSecret -Destination (Join-Path $target 'private/node.secret');Copy-Item -LiteralPath $Certificate -Destination (Join-Path $target 'private/tls/cert.pem');Copy-Item -LiteralPath $PrivateKey -Destination (Join-Path $target 'private/tls/key.pem')
Copy-Item -LiteralPath (Join-Path $PSScriptRoot '../deploy/signaling/docker-compose.yml') -Destination $target
$lines=@("RA_GO_IMAGE=$GoImage","RA_RUNTIME_IMAGE=$RuntimeImage",('RA_ALLOWED_ORIGINS='+$ViewerOrigin.Authority),('RA_TURN_URLS='+($TurnUrls-join',')))
[IO.File]::WriteAllLines((Join-Path $target '.env'),$lines,(New-Object Text.UTF8Encoding($false)))
Write-Output 'Staging prepared. Copy secrets privately, set Linux owner 65532 and mode 0700/0600, and build from the reviewed repository checkout.'
